/**
 * Resolves a free-text location string to { x, y, label, state }
 */
function resolveLocationCoordinates(locationStr) {
    if (!locationStr) return null;
    const clean = locationStr.toUpperCase().replace(/[.,\/#!$%^&*;:{}=\-_`~()]/g, ' ');
    const words = clean.split(/\s+/).filter(Boolean);

    for (const [cityKey, cityData] of Object.entries(US_CITIES_COORDS)) {
        if (clean.includes(cityKey)) {
            return {
                x: cityData.x,
                y: cityData.y,
                label: cityData.name,
                state: cityData.state
            };
        }
    }

    for (const [code, info] of Object.entries(US_STATES_DATA)) {
        const hasCode = words.includes(code);
        const hasName = clean.includes(info.name.toUpperCase());
        if (hasCode || hasName) {
            return {
                x: info.center.x,
                y: info.center.y,
                label: `${info.name}`,
                state: code
            };
        }
    }

    return null;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { US_STATES_DATA, US_CITIES_COORDS, resolveLocationCoordinates };
}
